  records.forEach(r=>{r.files=(r.files||[]).filter(f=>!f.sample&&f.data);r.follows.forEach((f,i)=>{f.id??=r.id+'-history-'+i;f.files=(f.files||[]).filter(file=>!file.sample&&file.data)});r.messages=(r.messages||[]).filter(m=>!String(m.type||'').includes('示例')).map(m=>({...m,files:(m.files||[]).filter(f=>!f.sample&&f.data)}))});
  const demoChanged=completeDemoDetails(records),wechatChanged=completeWechatDetails(records);
  if(demoChanged||wechatChanged){try{localStorage.setItem(KEY,JSON.stringify(records))}catch(e){readFailure=true}}
  let root,portal,filters={},page=1,pageSize=10,more=false,layers=[],main=null,backgroundState=[],bodyOverflow='',toastTimer;
  function persist(next){try{localStorage.setItem(KEY,JSON.stringify(next));records=next;return true}catch(e){toast('本地保存失败，请减少附件后重试；已保留当前输入。');return false}}
  function toast(message){document.getElementById('uc-toast')?.remove();const el=document.createElement('div');el.id='uc-toast';el.className='uc-scope uc-toast';el.setAttribute('role','status');el.textContent=message;document.body.appendChild(el);clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.remove(),4000)}
