  function lockBackground(){bodyOverflow=document.body.style.overflow;document.body.style.overflow='hidden';backgroundState=[...document.body.children].filter(el=>el!==portal&&el.id!=='uc-toast'&&!['SCRIPT','STYLE','LINK'].includes(el.tagName)).map(el=>({el,inert:el.inert}));backgroundState.forEach(({el})=>el.inert=true)}
  function unlockBackground(){backgroundState.forEach(({el,inert})=>el.inert=inert);backgroundState=[];document.body.style.overflow=bodyOverflow}
  function openLayer(title,body,footer,level=1){const trigger=document.activeElement,parent=layers.at(-1),parentView=parent?{scroll:parent.el.querySelector('.uc-drawer-body').scrollTop,tab:main?.tab}:null;if(!layers.length)lockBackground();else layers.at(-1).el.inert=true;const el=document.createElement('div');el.className='uc-scope uc-layer'+(level===2?' uc-level-2':'');el.innerHTML=`<div class="uc-shade" data-uc="dismiss"></div><section class="uc-drawer" role="dialog" aria-modal="true" aria-label="${esc(title)}" tabindex="-1"><header class="uc-drawer-head"><span class="uc-drawer-title">${esc(title)}</span><button type="button" class="uc-icon-btn" data-uc="dismiss" aria-label="关闭${esc(title)}">${iconClose}</button></header><div class="uc-layer-top"></div><div class="uc-drawer-body">${body}</div><footer class="uc-drawer-foot">${footer}</footer></section>`;portal.appendChild(el);const layer={el,trigger,title,closing:false,parentView};layers.push(layer);requestAnimationFrame(()=>requestAnimationFrame(()=>{el.classList.add('uc-entered');el.querySelector('.uc-drawer').focus({preventScroll:true})}));return layer}
  function closeLayer(force=false){const layer=layers.at(-1);if(!layer||layer.closing)return;if(!force&&dirty(layer)){showDiscard(layer);return}layer.closing=true;layer.el.classList.remove('uc-entered');setTimeout(()=>{layer.el.remove();layers.pop();if(main?.editor?.layer===layer)main.editor=null;if(layers.length){const parent=layers.at(-1);parent.el.inert=false;if(layer.parentView){parent.el.querySelector('.uc-drawer-body').scrollTop=layer.parentView.scroll;if(main?.layer===parent)setDetailTab(layer.parentView.tab)}}else{unlockBackground();main=null}if(layer.trigger?.isConnected)layer.trigger.focus({preventScroll:true});else if(layers.length)layers.at(-1).el.querySelector('.uc-drawer').focus({preventScroll:true});else root.querySelector('input,button')?.focus({preventScroll:true})},matchMedia('(prefers-reduced-motion: reduce)').matches?0:290)}
  function dirty(layer){const e=main?.editor;return Boolean(e?.layer===layer&&(e.uploading||JSON.stringify(e.draft)!==e.baseline||(e.selectingOrders&&JSON.stringify(e.selection)!==e.selectionBaseline)))}
  function showDiscard(layer,action='close'){layer.discardAction=action;const foot=layer.el.querySelector('.uc-drawer-foot');if(foot.querySelector('.uc-discard'))return;layer.oldFoot=foot.innerHTML;foot.innerHTML=`<div class="uc-discard" role="alert"><span>有尚未保存的修改，是否放弃？</span>${link('继续填写','keep')}${btn('放弃修改','discard')}</div>`;foot.querySelector('button').focus()}
  function restoreFoot(layer){if(layer.oldFoot){layer.el.querySelector('.uc-drawer-foot').innerHTML=layer.oldFoot;layer.oldFoot=null;layer.discardAction=null}}
  function recordById(id){return records.find(r=>r.id===id)}
  function isAssessed(r){return ASSESSMENT_FIELDS.every(([key])=>valueText(r[key]).trim())}
  function valuesFrom(r,fields){return Object.fromEntries(fields.map(([key])=>[key,MULTI_FIELDS.includes(key)?multiValues(r[key]):r[key]||'']))}
  function recognitionSnapshot(r){return {...Object.fromEntries(RECOGNITION_FIELDS.map(([key])=>[key,MULTI_FIELDS.includes(key)?multiValues(r[key]):String(r[key]||'').trim()])),linked:clone(r.linked),handlingPlan:r.handlingPlan||'',handlingFiles:clone(r.handlingFiles||[])}}
  function recognitionLog(snapshot){return {...snapshot,handlingFiles:(snapshot.handlingFiles||[]).map(({name,type,size})=>({name,type,size}))}}
  function handlingMissing(draft){return [['department',multiValues(draft.department).length,'请选择责任部门'],['type',String(draft.type||'').trim(),'请选择售后类型'],['responsible',multiValues(draft.responsible).length,'请选择责任人'],['level',String(draft.level||'').trim(),'请选择客诉等级'],['handlingPlan',validPlan(draft.handlingPlan),'请选择处理结果']].filter(([,value])=>!value).map(([name,,message])=>[name,message])}
  function recordRecognition(r,draft,time){
    if(r.status==='已完成'||handlingMissing(draft).length)return null;
    const before=recognitionSnapshot(r),after=recognitionSnapshot({...draft,linked:r.linked}),wasAssessed=r.status!=='待处理',beforeStatus=r.status;
    after.handlingPlan=draft.handlingPlan;
    const unchanged=JSON.stringify(before)===JSON.stringify(after);
    if(unchanged&&wasAssessed&&beforeStatus!=='待处理')return null;
    Object.assign(r,clone(after),{assessedAt:time,assessedBy:ACTOR,status:after.handlingPlan==='resolved'?'已完成':'处理中'});
    if(r.status==='已完成'&&beforeStatus!=='已完成'){r.closedAt=time;r.closedBy=ACTOR}
    const entry={id:r.id+'-handling-'+Date.now()+'-'+r.follows.length,kind:'handling',action:wasAssessed?'修改处理方案':'处理',time,actor:ACTOR,note:after.reason,status:r.status,beforeStatus,before,...clone(after),files:[]};
    r.follows.unshift(entry);return entry;
  }
  function recordFollow(r,d,time){if(r.status!=='处理中')return null;const beforeStatus=r.status;const entry={id:r.id+'-'+Date.now()+'-'+r.follows.length,kind:'follow',time,actor:ACTOR,note:d.note.trim(),files:clone(d.files),beforeStatus,status:r.status,...recognitionSnapshot(r)};r.follows.unshift(entry);return entry}
  function recordClosure(r,time){if(r.status!=='处理中')return null;const beforeStatus=r.status;r.status='已完成';r.handlingPlan='resolved';r.closedAt=time;r.closedBy=ACTOR;const entry={id:r.id+'-close-'+Date.now(),kind:'closure',time,actor:ACTOR,note:'已确认客诉处理完成，予以结案。',status:r.status,beforeStatus,...recognitionSnapshot(r),files:[]};r.follows.unshift(entry);return entry}
  function detailActions(r){if(r.status==='已完成')return btn('关闭','dismiss');return r.status==='待处理'?btn('处理','begin-assessment','',true):btn('写跟进','write-follow')+btn('结案','close-case','',true)}
  function openComplaint(id,tab='attribution'){
    if(layers.length)return;main={record:recordById(id),tab:tab==='follows'?'follows':'attribution',scrollPositions:{},expandedOrders:[],layer:null,editor:null};
    main.layer=openLayer('投诉详情','','');renderDetail();
  }
  function summary(r){return `<div class="uc-case-context"><div class="uc-case-customer"><strong>${esc(r.name)}</strong><span>${esc(r.phone)}</span><div class="uc-actions">${statusTag(r.status)}${levelTag(r.level)}</div></div><div class="uc-case-meta"><span>${CHANNELS[r.channel]}</span>${r.channel==='wechat'?'':`<span>${fmt(r.created)}</span>`}<span>工单号：${r.id}</span><span>发起人：${esc(r.submitter)}</span>${r.channel==='wechat'?'':`<span>原单号：${esc(r.sourceId)}</span>`}${r.contactTime?`<span>${esc(interval(r))}</span>`:''}</div><div class="uc-case-issue"><div class="uc-case-row"><span class="uc-fact-label">投诉内容</span><div>${esc(r.content)}</div></div>${r.files?.length?`<div class="uc-case-photos" aria-label="投诉图片">${filesView(r.files,'original')}</div>`:''}</div></div>`}
  function sections(){return [['attribution','处理方案'],['follows','跟进记录']]}
  function detailTabs(){return `<nav class="uc-tabs" role="tablist" aria-label="投诉详情">${sections().map(([id,label])=>`<button type="button" role="tab" class="uc-tab" id="uc-tab-${id}" aria-selected="${main.tab===id}" tabindex="${main.tab===id?'0':'-1'}" aria-controls="uc-section-${id}" data-uc="tab" data-tab="${id}">${label}</button>`).join('')}</nav>`}
  function panel(id,content){return `<section class="uc-tab-panel" role="tabpanel" id="uc-section-${id}" aria-labelledby="uc-tab-${id}" ${main.tab===id?'':'hidden'}>${content}</section>`}
  function setDetailTab(key){if(!main?.layer)return;main.tab=key;main.layer.el.querySelectorAll('.uc-tab').forEach(b=>{const active=b.dataset.tab===key;b.setAttribute('aria-selected',active);b.tabIndex=active?0:-1});main.layer.el.querySelectorAll('.uc-tab-panel').forEach(p=>p.hidden=p.id!=='uc-section-'+key)}
  function selectDetailTab(key,focus=true){const body=main.layer.el.querySelector('.uc-drawer-body'),scroll=body.scrollTop,tabTop=body.querySelector('.uc-detail-common').offsetHeight;main.scrollPositions[main.tab]=scroll;setDetailTab(key);body.scrollTop=scroll<=tabTop?scroll:Math.max(tabTop,main.scrollPositions[key]||0);if(focus)main.layer.el.querySelector('#uc-tab-'+key)?.focus({preventScroll:true})}
  function renderDetail(){if(!main.layer)return;const r=main.record,layer=main.layer,body=layer.el.querySelector('.uc-drawer-body');if(body.children.length)main.scrollPositions[main.tab]=body.scrollTop;layer.el.querySelector('.uc-drawer').classList.add('uc-detail-drawer','uc-workspace');layer.el.querySelector('.uc-layer-top').innerHTML='';body.classList.add('uc-detail-body');body.innerHTML=`<section class="uc-detail-common" aria-label="公共客户资料">${summary(r)}${r.channel==='wechat'?paymentView(r):''}<div class="uc-common-orders">${ordersView(r)}</div></section>${detailTabs()}<div class="uc-detail-panels">${panel('attribution',handlingSchemeView(r))}${panel('follows',followHistory(r)+(r.channel==='wechat'?wechatView(r):''))}</div>`;body.scrollTop=main.scrollPositions[main.tab]||0;layer.el.querySelector('.uc-drawer-foot').innerHTML=detailActions(r)}
  function paymentListSummary(r){return r.channel==='wechat'?`<div class="uc-payment-list-summary"><span>订单 ${esc(paymentMoney(r.paymentAmount))}</span><span>申请退款 ${esc(paymentMoney(r.refund))}</span></div>`:''}
  function paymentView(r){const read=(label,value,full=false)=>detail(label,valueText(value).trim()||'—',full);return `<section class="uc-channel-payment" aria-label="微信支付信息"><div class="uc-section-head"><h4>微信支付信息</h4><div class="uc-channel-state"><span>微信投诉状态</span>${r.channelStatus?statusTag(r.channelStatus):'—'}</div></div><div class="uc-details uc-payment-facts">${read('商户名称',r.merchant)}${read('商户号',r.merchantId)}${read('微信投诉单号',r.sourceId)}${read('投诉时间',r.created?fmt(r.created):'')}${read('外部单号',r.externalOrder)}${read('客户昵称',r.wechatNickname)}${read('问题类型',r.problemType)}${read('问题描述',r.problemDescription)}${read('订单金额',paymentMoney(r.paymentAmount))}${read('申请退款金额',paymentMoney(r.refund))}</div><details class="uc-inline-details uc-payment-more"><summary>更多支付资料</summary><div class="uc-details">${read('微信支付订单号',r.payOrder,true)}${read('投诉次数',r.complaintCount===undefined||r.complaintCount===null?'':r.complaintCount+' 次')}${read('风险状态',r.riskStatus)}</div></details></section>`}
  function resolveLink(item){const order=orders.find(o=>o.id===item.id);return {order,wx:order?.wechatChoices.find(w=>w.id===(item.wechatId||order.bookingWechatId))}}
  function orderCards(linked,editor=false){
    const expandedIds=editor?main.editor.expandedOrders:main.expandedOrders;
    return `<div class="uc-table-wrap"><table class="uc-table uc-order-table"><colgroup><col style="width:145px"><col style="width:135px"><col style="width:105px"><col style="width:190px"><col style="width:150px"><col style="width:56px"></colgroup><thead><tr><th>客户信息</th><th>预约门店</th><th>订单意向</th><th>服务项目</th><th>到店时间</th><th>操作</th></tr></thead><tbody>${linked.map(item=>{
      const {order:o,wx}=resolveLink(item);if(!o)return '';
      const expanded=expandedIds.includes(o.id),rowId='uc-order-extra-'+(editor?'edit-':'detail-')+o.id;
      const acquisition=esc(wx?.record||'未记录')+(wx?.account?`<span class="uc-block uc-muted">${esc(wx.account)}</span>`:'');
      return `<tr><td><strong class="uc-data-main">${esc(o.name)}</strong><span class="uc-block uc-muted">${esc(o.phone)}</span></td><td>${esc(o.store)}</td><td>${esc(o.intention||'未记录')}</td><td>${esc(o.project)}<span class="uc-block uc-muted">${esc(o.id)}</span></td><td class="uc-order-arrived">${esc(fmt(o.arrived))}</td><td>${link(expanded?'收起':'展开','toggle-order',`data-order="${o.id}" data-editor="${editor}" aria-expanded="${expanded}" aria-controls="${rowId}"`)}</td></tr><tr id="${rowId}" class="uc-order-extra-row" ${expanded?'':'hidden'}><td colspan="6"><div class="uc-details uc-order-expanded">${detail('加微记录',acquisition,false,true)}${detail('推广',wx?.promoter||'待核实')}${detail('咨询',o.consultant||'未记录')}${detail('接待销售',o.receptionSales||'未记录')}${detail('项目接待',o.reception)}${detail('操作',o.operator)}${detail('店长',o.manager)}</div></td></tr>`;
    }).join('')}</tbody></table></div>`;
  }
  function ordersView(r){return section('关联订单',r.linked.length?orderCards(r.linked):empty('暂未关联订单'),r.status==='已完成'?'':btn(r.linked.length?'调整订单':'关联订单','pick-orders'))}
  function toggleOrder(button){const ids=button.dataset.editor==='true'?main.editor.expandedOrders:main.expandedOrders,id=button.dataset.order,index=ids.indexOf(id);if(index<0)ids.push(id);else ids.splice(index,1);const row=document.getElementById(button.getAttribute('aria-controls'));row.hidden=index>=0;button.textContent=row.hidden?'展开':'收起';button.setAttribute('aria-expanded',String(!row.hidden))}
  function responsibilityRule(type){if(type==='广告宣传')return '广告效果 → 推广人';if(['光电操作','脱毛操作'].includes(type))return '操作问题 → 操作老师';if(type==='门店服务')return '服务态度 → 门店';return ''}
  function assessmentView(r){const read=(fields)=>`<div class="uc-details">${fields.map(([key,label])=>detail(label,key==='contactTime'?(r[key]?fmt(r[key]):'未填写'):(valueText(r[key])||'未填写'),['customerStatement','reason'].includes(key))).join('')}</div>`;return section('客户反馈',read(CONTACT_FIELDS))+section('责任认定',read(ASSESSMENT_FIELDS)+`<div class="uc-details uc-plan-detail">${detail('处理结果',planText(r.handlingPlan),true)}${r.handlingFiles?.length?detail('附件',filesView(r.handlingFiles,'handling'),true,true):''}</div>`,r.status==='已完成'?'':link('编辑','begin-assessment','aria-label="编辑处理方案"'))}
  function handlingSchemeView(r){if(r.status==='待处理')return empty('暂未处理');return `<article class="uc-scheme-card" aria-label="处理方案"><div class="uc-scheme-content">${assessmentView(r)}</div>${r.assessedAt||r.closedAt?`<footer class="uc-scheme-meta">${r.assessedAt?`<span>处理人：${esc(r.assessedBy||ACTOR)}</span><span>处理时间：${fmt(r.assessedAt)}</span>`:''}${r.closedAt?`<span>结案时间：${fmt(r.closedAt)}</span>`:''}</footer>`:''}</article>`}
  function events(items,render){return `<div class="uc-timeline">${items.map(item=>`<article class="uc-event"><time class="uc-event-time">${esc(fmt(item.time))}</time><div class="uc-event-content">${render(item)}</div></article>`).join('')}</div>`}
  function followHistory(r){return r.follows.length?events(r.follows,f=>{
    if(['assessment','handling'].includes(f.kind))return `<div class="uc-event-title"><strong>${esc(f.actor)}</strong>${tag(String(f.action||'').includes('修改')?'修改处理方案':'处理','blue')}</div><div class="uc-recognition-summary">${[f.department,f.type,f.responsible,f.level].map(valueText).filter(Boolean).map(value=>`<span>${esc(value)}</span>`).join('')}</div><div class="uc-event-text">责任原因：${esc(f.reason||'未填写')}</div>${f.handlingPlan?`<div class="uc-event-text">处理结果：${esc(planText(f.handlingPlan))}</div>`:''}${filesView(f.handlingFiles||[],'handling-history',r.follows.indexOf(f))}<div class="uc-saved-meta">首次反馈：${esc(f.firstContact||'未填写')} · ${fmt(f.contactTime)}</div>`;
    if(f.kind==='closure')return `<div class="uc-event-title"><strong>${esc(f.actor)}</strong>${tag('结案','green')}</div><div class="uc-event-text">${esc(f.note||'未填写跟进内容')}</div>`;
    return `<div class="uc-event-title"><strong>${esc(f.actor)}</strong>${tag('沟通跟进')}${f.actor===ACTOR?link('编辑','edit-follow-record',`data-follow="${esc(f.id)}" aria-label="编辑跟进 ${esc(fmt(f.time))}"`):''}</div><div class="uc-event-text">${esc(f.note||'未填写跟进内容')}</div>${filesView(f.files||[],'follow',r.follows.indexOf(f))}${f.updatedAt?`<div class="uc-saved-meta">修改于 ${fmt(f.updatedAt)}</div>`:''}`;
  }):empty('暂无跟进记录')}
  function wechatView(r){return r.messages?.length?`<details class="uc-inline-details uc-channel-disclosure"><summary>微信协商记录</summary>${events([...r.messages].reverse(),m=>`<div class="uc-event-title"><strong>${esc(m.actor)}</strong>${tag(m.type,'blue')}</div><div class="uc-event-text">${esc(m.text)}</div>${filesView(m.files||[],'message',r.messages.indexOf(m))}`)}</details>`:''}
  function filesView(files,kind,index=''){return files?.length?`<div class="uc-attachments uc-image-gallery">${files.map((f,i)=>String(f.data||'').startsWith('data:image/')?`<button type="button" class="uc-image-thumb" data-uc="file" data-kind="${kind}" data-index="${index}" data-file="${i}" aria-label="查看图片：${esc(f.name)}"><img src="${esc(f.data)}" alt="${esc(f.name)}" loading="lazy"><span>${esc(f.name)}</span></button>`:`<button type="button" class="uc-file uc-file-download" data-uc="file" data-kind="${kind}" data-index="${index}" data-file="${i}" aria-label="${isAudioFile(f)?'播放录音':'下载附件'}：${esc(f.name)}">${iconFile}<span>${esc(f.name)}</span><span class="uc-link">${isAudioFile(f)?'播放':'下载'}</span></button>`).join('')}</div>`:''}
  function draftFiles(files){return files.length?`<div class="uc-attachments">${files.map((f,i)=>`<div class="uc-file"><span>${esc(f.name)}</span>${link('移除','remove-file',`data-file="${i}"`)}</div>`).join('')}</div>`:''}

  function openEditor(kind,draft,followId=null){if(main.editor)return;const e={kind,draft,baseline:JSON.stringify(draft),followId,expandedOrders:[],selectingOrders:kind==='orders',uploading:false};if(kind==='orders'){e.orderPage=1;e.orderPageSize=10;e.selection=clone(draft.linked);e.selectionBaseline=JSON.stringify(e.selection);e.orderSearch={start:'',end:'',keywordType:'phone',keyword:main.record.phone||'',consultant:''};e.orderFilters=clone(e.orderSearch)}main.editor=e;e.layer=openLayer(kind==='orders'?(draft.linked.length?'调整关联订单':'关联订单'):kind==='assessment'?'处理':followId?'编辑跟进':'写跟进','','',main.layer?2:1);e.layer.editor=true;e.layer.el.querySelector('.uc-drawer').classList.add('uc-operation-drawer',kind==='orders'?'uc-orders-editor':kind==='assessment'?'uc-assessment-drawer':'uc-follow-editor');renderEditor()}
  function editorContext(){const r=main.record;return `<div class="uc-editor-context"><div><strong>${esc(r.name)}</strong><span>${esc(r.phone)}</span><span>${esc(r.store)}</span></div><div class="uc-muted">投诉 ${r.id} · ${CHANNELS[r.channel]} · ${fmt(r.created)}${statusTag(r.status)}</div></div>`}
  function renderEditor(resetScroll=false){const e=main.editor;if(!e)return;const body=e.layer.el.querySelector('.uc-drawer-body'),scroll=resetScroll?0:body.scrollTop;e.layer.el.querySelector('.uc-layer-top').innerHTML=editorContext();body.classList.add('uc-editor-body');body.innerHTML=e.kind==='orders'?orderPickerView():e.kind==='assessment'?assessmentForm():followForm();body.scrollTop=scroll;renderEditorFooter()}
  function renderEditorFooter(){const e=main.editor;if(!e)return;const foot=e.layer.el.querySelector('.uc-drawer-foot');if(foot.querySelector('.uc-discard'))return;if(e.kind==='orders'){foot.innerHTML=btn('取消','dismiss')+btn('保存关联','confirm-orders','',true);return}foot.innerHTML=btn('取消','dismiss')+btn(e.kind==='assessment'?(e.draft.handlingPlan==='resolved'&&main.record.status!=='已完成'?'提交并结案':'保存处理'):e.followId?'保存修改':'保存跟进',e.kind==='assessment'?'save-assessment':'save-follow',e.uploading?'disabled':'',true)}
  function contactForm(){const d=main.editor.draft;return `<div class="uc-grid">${field('firstContact','客诉第一联系人',input('firstContact',d.firstContact,'以客户陈述为准','text','maxlength="80"'),false)}${field('contactTime','投诉时间',input('contactTime',d.contactTime,'','datetime-local'),false)}${field('complaintStore','投诉门店',complaintStoreControl(d.complaintStore),false)}${field('customerStatement','客户陈述',input('customerStatement',d.customerStatement,'补充客户原话（选填）','text','maxlength="500"'),false,'',true)}</div>`}
  function complaintStores(){return [...new Set([...customers.map(c=>c[2]),...orders.map(o=>o.store),main?.editor?.draft.complaintStore].filter(Boolean))]}
  function complaintStoreControl(value=''){return `<div class="uc-store-select"><div class="uc-store-control"><input id="uc-complaintStore" class="uc-input" type="text" role="combobox" aria-autocomplete="list" aria-haspopup="listbox" aria-expanded="false" aria-controls="uc-complaintStore-options" autocomplete="off" placeholder="请选择或输入搜索门店" value="${esc(value)}" data-store-search data-uc="store-open"><button type="button" class="uc-store-clear" data-uc="store-clear" aria-label="清空投诉门店" ${value?'':'hidden'}>×</button><button type="button" class="uc-store-toggle" data-uc="store-toggle" aria-label="展开门店选项" tabindex="-1"><span class="uc-multi-arrow" aria-hidden="true"></span></button></div><div class="uc-store-menu" id="uc-complaintStore-options" role="listbox" aria-label="投诉门店选项" hidden></div></div>`}
