      <div class="uc-order-filter-row uc-order-keyword-filter"><label class="uc-order-filter-label" for="uc-orderKeyword">关键词</label><div class="uc-order-keyword-control"><select id="uc-orderKeywordType" name="keywordType" class="uc-input" aria-label="关键词类型">${ORDER_KEYWORDS.map(([key,label])=>`<option value="${key}"${q.keywordType===key?' selected':''}>${label}</option>`).join('')}</select>${input('orderKeyword',q.keyword,'输入'+keywordLabel,'text','aria-label="订单关键词"').replace('name="orderKeyword"','name="keyword"')}</div></div>
